-- Standar QA dinamis CPR (21 Nov 2026): indikator, bobot, dan critical check per jenis konten (FIP/VPD/VRV/VEV)
-- disimpan di MediaSettings.extra.qaCfg supaya bisa diubah admin penuh dari Studio (tab CPR → Standar QA).
-- Aman dijalankan berulang: hanya mengisi bila qaCfg belum ada; standar yang sudah diubah admin tidak ditimpa.
-- Content Brief (tasks.brief) dan hasil QA (tasks.qa) tersimpan di kolom extra MediaTask (JSON), tanpa perubahan tabel.
INSERT INTO "MediaSettings" ("id", "extra", "updatedAt")
VALUES (1, jsonb_build_object('qaCfg', '{"v":1,"types":{"igf":[{"k":"acc","l":"Product Accuracy","w":25,"c":true,"d":"Nama, varian, warna, harga/promo sesuai produk"},{"k":"vis","l":"Visual Quality","w":25,"d":"Ketajaman, cahaya, warna, retouch"},{"k":"comp","l":"Composition & Branding","w":20,"d":"Komposisi, ruang kosong, identitas Tirtonic"},{"k":"cap","l":"Caption & CTA","w":15,"d":"Caption jelas, ajakan bertindak"},{"k":"tech","l":"Technical Readiness","w":15,"d":"Rasio, resolusi, urutan slide, file final"}],"vpr":[{"k":"acc","l":"Product Accuracy","w":25,"c":true,"d":"Nama, varian, warna, harga/promo, spesifikasi sesuai produk"},{"k":"show","l":"Product Showcase","w":20,"d":"Fitur & detail produk terlihat jelas"},{"k":"prod","l":"Production Quality","w":20,"d":"Cahaya, framing, gerak kamera, editing"},{"k":"hook","l":"Hook & Storytelling","w":15,"d":"3 detik awal menahan, alur jelas"},{"k":"cta","l":"CTA & Branding","w":10,"d":"Ajakan jelas, identitas Tirtonic konsisten"},{"k":"tech","l":"Technical Readiness","w":10,"d":"Rasio, resolusi, audio, subtitle, file final"}],"vrv":[{"k":"acc","l":"Accuracy & Credibility","w":30,"c":true,"d":"Fakta, spesifikasi, dan klaim bisa dipertanggungjawabkan"},{"k":"edu","l":"Educational Depth","w":25,"d":"Membantu audiens memahami kelebihan/kekurangan"},{"k":"str","l":"Structure & Clarity","w":15,"d":"Pembuka, isi, kesimpulan runtut"},{"k":"demo","l":"Demonstration Evidence","w":15,"d":"Ada bukti pemakaian / perbandingan nyata"},{"k":"audio","l":"Audio & Technical","w":10,"d":"Suara jernih, gambar stabil, subtitle"},{"k":"cta","l":"Balanced CTA","w":5,"d":"Ajakan tidak berlebihan, tetap jujur"}],"evt":[{"k":"acc","l":"Product Accuracy","w":25,"c":true,"d":"Nama, varian, warna, harga/promo, spesifikasi sesuai produk"},{"k":"show","l":"Product Showcase","w":20,"d":"Fitur & detail produk terlihat jelas"},{"k":"prod","l":"Production Quality","w":20,"d":"Cahaya, framing, gerak kamera, editing"},{"k":"hook","l":"Hook & Storytelling","w":15,"d":"3 detik awal menahan, alur jelas"},{"k":"cta","l":"CTA & Branding","w":10,"d":"Ajakan jelas, identitas Tirtonic konsisten"},{"k":"tech","l":"Technical Readiness","w":10,"d":"Rasio, resolusi, audio, subtitle, file final"}]},"checks":[{"k":"rights","l":"Hak penggunaan aset (musik, foto, talent, logo) aman"},{"k":"info","l":"Informasi akurat (harga, stok, spesifikasi, klaim)"},{"k":"brief","l":"Sesuai Content Brief yang disetujui"}]}'::jsonb), now())
